def get_cache_data(run):
    node = run.arg
    if not node.validate(run):
        return False
    else:
        run.sync.done(error=node.getError(), result=node.getData())

class SyncRequest(object):
    def __init__(self):
        self.cond = threading.Condition()
        self.error = None
        self.result = None

    def done(self, error=None, result=None):
        self.error = error
        self.result = result
        with self.cond:
            self.cond.notify()


class Runnable(object):
    def __init__(self, callable_function, arg=None):
        self.callable = callable_function
        self.arg = arg
        self.sync = SyncRequest()

    def __call__(self):
        return self.callable(self)

def get(self, timeout=None):
    """
    Waits if necessary for the computation to complete, and then
    retrieves its result.

    @return the computed result
    @throws CancellationException if the computation was canceled
    @throws ExecutionException if the computation threw an
    exception
    @throws InterruptedException if the current thread was interrupted
    while waiting
    """
    assert not protocol.isDispatchThread()
    with self._lock:
        while not self.isDone():
            self._lock.wait(timeout)
            if timeout and not self.isDone():
                raise TimeoutException("Timed out")
        if self.__error:
            raise Exception("TCF task aborted", self.__error)
        return self.__result

