def invokeAndWait(c, *args, **kwargs):
    """
    Causes callable to be called in the dispatch thread of the framework.
    Calling thread is suspended until the method is executed.
    If invokeAndWait is called from the dispatching thread
    the callable is executed immediately.

    This method can be invoked from any thread.

    @param c  the callable to be executed on dispatch thread.
    """
    if _event_queue.isDispatchThread():
        return c(*args, **kwargs)
    else:
        class DoRun():
            result = None

            def __call__(self):
                try:
                    self.result = c(*args, **kwargs)
                finally:
                    with runLock:
                        runLock.notify()

        doRun = DoRun()
        runLock = threading.Condition()
        with runLock:
            _event_queue.invokeLater(doRun)
            runLock.wait()
            return doRun.result

class TcfNodeMemoryMap(object):
    def __init__(self, __tcf_node_exec_ctx, channel, id: str):
        self.id = id
        self.channel = channel
        self.node = __tcf_node_exec_ctx
        # self.__get_memmap_data = self.MemMapGetData(channel, id)

    def set(self, memoryMap, sync=None):
        mm = self.channel.getRemoteService(memmap_service.NAME)

        class DoneSet(memmap_service.DoneSet):
            def __init__(self, sync):
                self.__sync = sync

            def doneSet(self, token, error):
                if self.__sync is not None:
                    self.__sync.done(error=error, result=None)

        mm.set(self.id, memoryMap, DoneSet(sync))

    def get(self, sync=None):

    def startDataRetrieval(self):
        mem = self.node.channel.getRemoteService(mem_service.NAME)
        mem_children = self

        class DoneGetChildren(mem_service.DoneGetChildren):
            def doneGetChildren(self, token, error, context_ids):
                data = {}
                if mem_children._command is token and error is None:
                    _logger.debug(' [R] {0:3s} [Memory getChildren] ---- {1}'.format(token.id, context_ids))
                    for context_id in context_ids:
                        if context_id in mem_children.node.info.get_nodes().keys():
                            n = mem_children.node.info.get_node(context_id)
                        else:
                            n = xsdb._tcf_node_exec_context.TcfNodeExecContext(mem_children.node, context_id)
                        assert n.parent == mem_children.node
                        data.update({context_id: n})
                        mem_children.node.info.update_nodes(data)
                mem_children.set(token, error, data)

        mem_children._command = mem.getChildren(self.node.id, DoneGetChildren())
        _logger.debug(' [C] {0:3s} [Memory getChildren] ---- {1}'.format(mem_children._command.id, self.node.id))
        return False

